4;;Dashboard về danh mục trái phiếu theo biểu đồ kỹ thuật;Kỳ báo cáo;;Dashboard;Chỉ tiêu cơ sở;TB;Mã CK;IDS;X;X;;Done;;Tham số lọc (không map bảng);:year (YYYY), :quarter (QX);Tham số đầu vào của báo cáo/dashboard;

;;;;Done;Dữ liệu tĩnh
9;;Top khối lượng theo sàn (HOSE/HNX/UPCOM), Bộ chỉ số tài chính, Bộ chỉ số ngành) theo dạng bảng số liệu;Bộ chỉ số thị trường;;Dashboard;Chiều;TB;Mã CK;MDDS;X;X;;Done;Thông tin thị trường;JAD_MARKETINFOR;MARKETCODE;MARKETCODE IN ('HOSE','UPCOM','HNX');;;;;;Done;Dữ liệu tĩnh;
9;;Top khối lượng theo sàn (HOSE/HNX/UPCOM), Bộ chỉ số tài chính, Bộ chỉ số ngành) theo dạng bảng số liệu;Bộ chỉ số theo ngành;;Dashboard;Chiều;TB;Mã CK;MDDS;X;X;;Done;Thông tin thị trường;JAD_MARKETINFOR;MARKETCODE;MARKETCODE NOT IN ('HOSE','UPCOM','HNX');;;;;;Done;Dữ liệu tĩnh;
9;;Top khối lượng theo sàn (HOSE/HNX/UPCOM), Bộ chỉ số tài chính, Bộ chỉ số ngành) theo dạng bảng số liệu;Ngành;Lấy theo bảng phân ngành IDS2;Dashboard;Chiều;Trùng;Mã CK;IDS;;X;;Done;theo ngành kinh tế cấp 1 trên IDS;IDS.categories (c);c.industry_cd, c.industry_name AS ten_nganh;c.active_flg = 1;SELECT c.industry_cd

;Foreigner Investor type IN ('10','20');;;;;;Done;Dữ liệu tĩnh;
33;;Top nhà đầu tư nước ngoài theo dạng bảng số liệu theo toàn thị trường;LNST;;Dashboard;Chỉ tiêu cơ sở;Trùng;Mã CK;IDS;;;;Done;lấy từ báo cáo tài chính IDS;IDS.data (d), IDS.report_catalog (rc), IDS.company_data (cd);SUM(d.data_value) AS lnst;rc2.col_desc = '1' AND rc.report_cd LIKE 'BCKQKD%' AND ((rc.enterprise_type_cd='dn' AND rr.row_desc='60') OR (rc.enterprise_type_cd='bh' AND rr.row_desc='60') OR (rc.enterprise_type_cd='td' AND rr.row_desc='21'));SELECT SUM(d.data_value) AS lnst FROM IDS.data d JOIN IDS.report_catalog rc ON d.report_catalog_id=rc.id JOIN IDS.rrow rr ON rr.row_cd = d.row_cd AND rr.report_catalog_id = d.report_catalog_id JOIN IDS.rcol rc2 ON rc2.col_cd = d.col_cd AND rc2.report_catalog_id = d.report_catalog_id JOIN IDS.company_data cd ON d.company_data_id=cd.id WHERE rc2.col_desc = '1' AND rc.report_cd LIKE 'BCKQKD%' AND cd.report_year=:year AND cd.report_quarter=:quarter AND ((rc.enterprise_type_cd='dn' AND rr.row_desc IN ('60')) OR (rc.enterprise_type_cd='bh' AND rr.row_desc IN ('60')) OR (rc.enterprise_type_cd='td' AND rr.row_desc IN ('21')));;;;;Done;Dữ liệu tĩnh;
33;;Top nhà đầu tư nước ngoài theo dạng bảng số liệu theo toàn thị trường;VCSH;;Dashboard;Chỉ tiêu cơ sở;Trùng;Mã CK;IDS;;;;Done;lấy từ báo cáo tài chính IDS;IDS.data (d)

;Foreigner Investor type IN ('10','20');;;;;;Done;Dữ liệu tĩnh;
35;;Top nhà đầu tư nước ngoài theo dạng bảng số liệu theo sàn (HOSE/HNX/UPCOM), Bộ chỉ số tài chính, Bộ chỉ số ngành;LNST;;Dashboard;Chỉ tiêu cơ sở;Trùng;Mã CK;IDS;;;;Done;lấy từ báo cáo tài chính IDS;IDS.data (d), IDS.report_catalog (rc), IDS.company_data (cd);SUM(d.data_value) AS lnst;rc2.col_desc = '1' AND rc.report_cd LIKE 'BCKQKD%' AND ((rc.enterprise_type_cd='dn' AND rr.row_desc='60') OR (rc.enterprise_type_cd='bh' AND rr.row_desc='60') OR (rc.enterprise_type_cd='td' AND rr.row_desc='21'));SELECT SUM(d.data_value) AS lnst FROM IDS.data d JOIN IDS.report_catalog rc ON d.report_catalog_id=rc.id JOIN IDS.rrow rr ON rr.row_cd = d.row_cd AND rr.report_catalog_id = d.report_catalog_id JOIN IDS.rcol rc2 ON rc2.col_cd = d.col_cd AND rc2.report_catalog_id = d.report_catalog_id JOIN IDS.company_data cd ON d.company_data_id=cd.id WHERE rc2.col_desc = '1' AND rc.report_cd LIKE 'BCKQKD%' AND cd.report_year=:year AND cd.report_quarter=:quarter AND ((rc.enterprise_type_cd='dn' AND rr.row_desc IN ('60')) OR (rc.enterprise_type_cd='bh' AND rr.row_desc IN ('60')) OR (rc.enterprise_type_cd='td' AND rr.row_desc IN ('21')));;;;;Done;Dữ liệu tĩnh;
35;;Top nhà đầu tư nước ngoài theo dạng bảng số liệu theo sàn (HOSE/HNX/UPCOM), Bộ chỉ số tài chính, Bộ chỉ số ngành;VCSH;;Dashboard;Chỉ tiêu cơ sở;Trùng;Mã CK;IDS;;;;Done;lấy từ báo cáo tài chính IDS;IDS.data (d)
